      url: llm.url,
      provider: llm.provider || 'anthropic',
      anthropic_version: llm.anthropic_version || '2023-06-01',
      body: H.buildBody(p, userText, llm),
      meta: {
        persona_id: personaId,
        persona_name: p.name,
        persona_title: p.title,
        emoji: p.emoji || '🗣️',
        output_mode: p.output_mode || 'json',
