      }
      if (!line.trim()) { flush(); continue; }
      buf.push(line);
    }
    flush();
    const linkRe = /\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g;
    let m;
    while ((m = linkRe.exec(out.body)) !== null) {
      out.links.push({ anchor: m[1].trim(), url: m[2].trim() });
    }
    const bareRe = /(?:^|[\s(<])((?:https?:\/\/)[^\s)<>\]"']+)/g;
    while ((m = bareRe.exec(out.body)) !== null) {
