    plan.push({ key: '__sources__', order: plan.length, heading: 'المصادر المستخدمة',
                purpose: 'تُبنى آليًا من الأدلة المستشهد بها فعليًا', word_budget: 0, format: 'auto', must_include: [] });
  }
