  });
  if (wantKw > 0 && kw) {
    let left = wantKw;
    if (out.__front__) { out.__front__.target_kw = Math.min(2, left); left -= out.__front__.target_kw; }
    const bodyKeys = flex.map(function (s) { return s.key; });
    bodyKeys.forEach(function (k, i) {
