    if (llm.provider && llm.provider !== 'anthropic') {
      const body = {
        model,
        temperature,
        max_tokens: maxTokens,
        messages: [
          { role: 'system', content: persona.system },
          { role: 'user',   content: userText }
        ]
      };
      if (wantsJson && llm.json_mode !== false) body.response_format = { type: 'json_object' };
