        state: state
      }, extra && extra.json ? extra.json : {})
    };
  },
  readText(r) {
    if (!r) return '';
    if (typeof r === 'string') return r;
    if (Array.isArray(r.content)) {
      return r.content
        .filter(function (b) { return b && b.type === 'text' && typeof b.text === 'string'; })
        .map(function (b) { return b.text; })
        .join('\n');
    }
    if (r.choices && r.choices[0]) {
