  },
  grabArticle(text) {
    if (!text) return '';
    const s = String(text);
    const m = s.match(/<<<ARTICLE>>>([\s\S]*?)<<<END_ARTICLE>>>/);
    if (m) return m[1].trim();
    const open = s.indexOf('<<<ARTICLE>>>');
    if (open >= 0) return s.slice(open + 13).trim();
    const fence = s.match(/```(?:markdown|md)?\s*([\s\S]*?)```/i);
    if (fence) return fence[1].trim();
    return s.trim();
  },
  stripMd(s) {
    return String(s || '')
      .replace(/```[\s\S]*?```/g, ' ')
      .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
      .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
      .replace(/^\s{0,3}#{1,6}\s+/gm, '')
      .replace(/^\s*[-*+]\s+/gm, '')
      .replace(/^\s*\d+[.)]\s+/gm, '')
      .replace(/[|>*_`~]/g, ' ')
      .replace(/^\s*-{3,}\s*$/gm, ' ');
  },
  words(s) {
    const t = H.stripMd(s).replace(/\s+/g, ' ').trim();
    if (!t) return 0;
    return t.split(' ').filter(function (w) { return /[\p{L}\p{N}]/u.test(w); }).length;
  },
  normAr(s) {
    return String(s || '')
      .replace(/[ً-ْـٰ]/g, '')
      .replace(/[آأإٱ]/g, 'ا')
      .replace(/ى/g, 'ي')
      .replace(/ة/g, 'ه')
      .replace(/\s+/g, ' ')
      .toLowerCase()
