    if (p.err || !p.md || tooShort) {
      failed.push(p.key + (p.err ? ' (' + p.err + ')' : tooShort ? ' (انكمش من ' + oldWords + ' إلى ' + newWords + ' كلمة)' : ' (فارغ)'));
