  const text = H.readText(raw);
  const err  = H.apiError(raw);
  const next = H.grabArticle(text);
  if (err || H.words(next) < H.words(s.article) * 0.5) {
    H.fail(s, 'revise', err || 'النسخة المعدّلة ناقصة — أُبقيت النسخة السابقة');
