    s.article = next;
    s.sections = H.splitSections(s.article);
    note = 'تم';
  }
  const ur = text.match(/<<<UPDATE_REPORT>>>([\s\S]*?)<<<END_UPDATE_REPORT>>>/);
  if (ur) s.update_report = H.grabJson(ur[1]) || s.update_report;
