if ((s.errors || []).length)   { ar.push('', '## أخطاء تقنية أثناء التشغيل', ''); s.errors.forEach(function (e) { ar.push('- [' + e.stage + '] ' + e.message); }); }

/* ---------- الحالة النهائية ---------- */
