  const totalKw = cur.reduce(function (n, s) { return n + s.kw; }, 0);
  const wantWords = R.word_count ? Math.round((R.word_count.min + R.word_count.max) / 2) : totalWords;
  const wantKw = state.brief.primary_keyword_count || 0;
