};
H.sectionTable = function (state) {
  const secs = H.splitSections(state.article || '');
  if (!secs.length) return '';
  const L = ['### توزيع الكلمات الحالي على الأقسام', '', '| القسم | الكلمات |', '|---|---|'];
  secs.forEach(function (s) {
